{"file_path":"src/parse.js","content":"/**
 * The parser for the configuration document. It turns the text of a document
 * into a tree of tagged nodes, or throws a ConfError naming the line and the
 * reason of the first failure.
 */

export class ConfError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

function newTable() {
  return { type: 'table', map: new Map(), headered: false }
}

function joinPath(parts) {
  return parts.join('.')
}

/** The parser of one line of the document. */
class LineParser {
  constructor(text, line) {
    this.s = text
    this.n = text.length
    this.i = 0
    this.line = line
  }

  fail(reason) {
    throw new ConfError(this.line, reason)
  }

  peek() {
    return this.i < this.n ? this.s[this.i] : undefined
  }

  skipWs() {
    while (this.i < this.n && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  /** True at the end of the line, a comment counting as the end. */
  atEnd() {
    if (this.i >= this.n) return true
    const c = this.s[this.i]
    return c === '#' || c === ';'
  }

  parseBasicString() {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.n) this.fail('unterminated string')
      const c = this.s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        this.i++
        if (this.i >= this.n) this.fail('unterminated string')
        const e = this.s[this.i]
        this.i++
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const hex = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.fail('invalid escape \\u')
          this.i += 4
          out += String.fromCharCode(parseInt(hex, 16))
        } else this.fail(`invalid escape \\${e}`)
      } else {
        out += c
        this.i++
      }
    }
  }

  parseLiteralString() {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.n) this.fail('unterminated string')
      const c = this.s[this.i]
      this.i++
      if (c === "'") return out
      out += c
    }
  }

  parseName() {
    const c = this.peek()
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    const start = this.i
    while (this.i < this.n && NAME_CHAR.test(this.s[this.i])) this.i++
    if (this.i === start) this.fail('expected a name')
    return this.s.slice(start, this.i)
  }

  parseDottedName() {
    const parts = [this.parseName()]
    for (;;) {
      const save = this.i
      this.skipWs()
      if (this.peek() === '.') {
        this.i++
        this.skipWs()
        parts.push(this.parseName())
      } else {
        this.i = save
        return parts
      }
    }
  }

  /** A value, `path` naming it for the sake of duplicate key messages. */
  parseValue(path) {
    this.skipWs()
    const c = this.peek()
    if (this.atEnd() || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"') return { type: 'string', value: this.parseBasicString() }
    if (c === "'") return { type: 'string', value: this.parseLiteralString() }
    if (c === '[') return this.parseArray(path)
    if (c === '{') return this.parseInlineTable(path)
    const start = this.i
    while (this.i < this.n && !' \t,]}'.includes(this.s[this.i])) this.i++
    const word = this.s.slice(start, this.i)
    if (word === 'true') return { type: 'boolean', value: true }
    if (word === 'false') return { type: 'boolean', value: false }
    const bare = word.replace(/_/g, '')
    if (INTEGER.test(word)) return { type: 'integer', value: BigInt(bare.replace(/^\+/, '')) }
    if (FLOAT.test(word) && /[.eE]/.test(word)) return { type: 'float', value: Number(bare) }
    this.fail(`invalid value ${word}`)
  }

  parseArray(path) {
    this.i++
    const items = []
    for (;;) {
      this.skipWs()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.peek() === ']') {
        this.i++
        return { type: 'array', items, ofTables: false }
      }
      items.push(this.parseValue(path))
      this.skipWs()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.peek() === ',') {
        this.i++
        continue
      }
      if (this.peek() === ']') {
        this.i++
        return { type: 'array', items, ofTables: false }
      }
      this.fail('unterminated array')
    }
  }

  parseInlineTable(path) {
    this.i++
    const table = newTable()
    this.skipWs()
    if (this.atEnd()) this.fail('unterminated inline table')
    if (this.peek() === '}') {
      this.i++
      return table
    }
    for (;;) {
      this.skipWs()
      if (this.atEnd()) this.fail('unterminated inline table')
      const parts = this.parseDottedName()
      this.skipWs()
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.i++
      const value = this.parseValue(path.concat(parts))
      const parent = this.descend(table, parts, path)
      const key = parts[parts.length - 1]
      if (parent.map.has(key)) {
        this.fail(`key ${joinPath(path.concat(parts))} is defined twice`)
      }
      parent.map.set(key, value)
      this.skipWs()
      if (this.atEnd()) this.fail('unterminated inline table')
      if (this.peek() === ',') {
        this.i++
        continue
      }
      if (this.peek() === '}') {
        this.i++
        return table
      }
      this.fail('unterminated inline table')
    }
  }

  /**
   * Walks every name of `parts` but the last from `table`, creating the tables
   * the dots pass through, and answers the table holding the last name.
   */
  descend(table, parts, basePath) {
    let current = table
    const seen = basePath.slice()
    for (let k = 0; k < parts.length - 1; k++) {
      const key = parts[k]
      seen.push(key)
      let held = current.map.get(key)
      if (held === undefined) {
        held = newTable()
        current.map.set(key, held)
      }
      if (held.type === 'table') current = held
      else if (held.type === 'array' && held.ofTables && held.items.length > 0) {
        current = held.items[held.items.length - 1]
      } else this.fail(`${joinPath(seen)} is not a table`)
    }
    return current
  }
}

/** Parses the whole document and answers its root table. */
export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable()
  let current = root
  let currentPath = []

  for (let n = 0; n < lines.length; n++) {
    const p = new LineParser(lines[n], n + 1)
    p.skipWs()
    if (p.atEnd()) continue

    if (p.peek() === '[') {
      p.i++
      let ofTables = false
      if (p.peek() === '[') {
        ofTables = true
        p.i++
      }
      p.skipWs()
      const parts = p.parseDottedName()
      p.skipWs()
      if (p.peek() !== ']') p.fail('unterminated table header')
      p.i++
      if (ofTables) {
        if (p.peek() !== ']') p.fail('unterminated table header')
        p.i++
      }
      p.skipWs()
      if (!p.atEnd()) p.fail('trailing text after a table header')

      const parent = p.descend(root, parts, [])
      const key = parts[parts.length - 1]
      const shown = joinPath(parts)
      let held = parent.map.get(key)
      if (!ofTables) {
        if (held === undefined) {
          held = newTable()
          parent.map.set(key, held)
        } else if (held.type !== 'table') {
          p.fail(`${shown} is not a table`)
        } else if (held.headered) {
          p.fail(`table ${shown} is defined twice`)
        }
        held.headered = true
        current = held
        currentPath = parts.slice()
      } else {
        if (held === undefined) {
          held = { type: 'array', items: [], ofTables: true }
          parent.map.set(key, held)
        } else if (held.type !== 'array' || !held.ofTables) {
          p.fail(`${shown} is not an array of tables`)
        }
        const fresh = newTable()
        held.items.push(fresh)
        current = fresh
        currentPath = parts.slice()
      }
      continue
    }

    const parts = p.parseDottedName()
    p.skipWs()
    if (p.peek() !== '=') p.fail('expected key = value')
    p.i++
    const value = p.parseValue(currentPath.concat(parts))
    p.skipWs()
    if (!p.atEnd()) p.fail('trailing text after a value')

    const parent = p.descend(current, parts, currentPath)
    const key = parts[parts.length - 1]
    if (parent.map.has(key)) {
      p.fail(`key ${joinPath(currentPath.concat(parts))} is defined twice`)
    }
    parent.map.set(key, value)
  }

  return root
}
