 * The two renderings of a parsed document: canonical JSON, and the listing of
 * the path and the type of every node below the root.
 */

/** Compares two keys by code point, ascending. */
function byCodePoint(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const c = x[i].codePointAt(0)
    const d = y[i].codePointAt(0)
    if (c !== d) return c < d ? -1 : 1
  }
  return x.length - y.length
}

function sortedKeys(table) {
  return Array.from(table.map.keys()).sort(byCodePoint)
}

function scalar(node) {
  switch (node.type) {
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.value.toString()
    case 'float':
      return Number.isFinite(node.value) ? String(node.value) : 'null'
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      return 'null'
  }
}

function render(node, depth) {
  const pad = '  '.repeat(depth)
  const inner = '  '.repeat(depth + 1)
  if (node.type === 'table') {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const parts = keys.map(
      (k) => `${inner}${JSON.stringify(k)}: ${render(node.map.get(k), depth + 1)}`,
    )
    return `{\n${parts.join(',\n')}\n${pad}}`
  }
  if (node.type === 'array') {
    if (node.items.length === 0) return '[]'
    const parts = node.items.map((item) => `${inner}${render(item, depth + 1)}`)
    return `[\n${parts.join(',\n')}\n${pad}]`
  }
  return scalar(node)
}

/** The document as JSON indented by two spaces, with a trailing newline. */
export function toJson(root) {
  return `${render(root, 0)}\n`
}

/** One line of `<path> <type>` for every node below the root. */
export function toKeys(root) {
  const out = []
  const walk = (node, path) => {
    if (node.type === 'table') {
      for (const key of sortedKeys(node)) {
        const child = node.map.get(key)
        const next = path === '' ? key : `${path}.${key}`
        out.push(`${next} ${child.type}\n`)
        walk(child, next)
      }
    } else if (node.type === 'array') {
      node.items.forEach((item, index) => {
        const next = `${path}[${index}]`
        out.push(`${next} ${item.type}\n`)
        walk(item, next)
      })
    }
  }
  walk(root, '')
  return out.join('')
}
